   120	    struct OccupiedVoxels : public CubeIndexEstimator
   121	    {
   122	      enum
   123	      {        
   124	        CTA_SIZE_X = 32,
   125	        CTA_SIZE_Y = 8,
   126	        CTA_SIZE = CTA_SIZE_X * CTA_SIZE_Y,
   127	
   128	        WARPS_COUNT = CTA_SIZE / Warp::WARP_SIZE
   129	      };
   130	
   131	      mutable int* voxels_indeces;
   132	      mutable int* vetexes_number;
   133	      int max_size;
   134	
   135	      __device__ __forceinline__ void
   136	      operator () () const
   137	      {
   138	        int x = threadIdx.x + blockIdx.x * CTA_SIZE_X;
   139	        int y = threadIdx.y + blockIdx.y * CTA_SIZE_Y;
   140	
   141	        if (__all_sync (__activemask (), x >= VOLUME_X)
   142	            || __all_sync (__activemask (), y >= VOLUME_Y))
   143	          return;
   144	
   145	        int ftid = Block::flattenedThreadId ();
   146			int warp_id = Warp::id();
   147			int lane_id = Warp::laneId();
   148	
   149	        volatile __shared__ int warps_buffer[WARPS_COUNT];
   150	
   151	        for (int z = 0; z < VOLUME_Z - 1; z++)
   152	        {
   153	          int numVerts = 0;
   154	          if (x + 1 < VOLUME_X && y + 1 < VOLUME_Y)
   155	          {
   156	            float field[8];
   157	            int cubeindex = computeCubeIndex (x, y, z, field);
   158	
   159	            // read number of vertices from texture
   160	            numVerts = (cubeindex == 0 || cubeindex == 255) ? 0 : tex1Dfetch (numVertsTex, cubeindex);
   161	          }
   162	
   163	          int total = __popc (__ballot_sync (__activemask (), numVerts > 0));
   164			  if (total == 0)
   165				continue;
   166	
   167	          if (lane_id == 0)
   168	          {
   169	            int old = atomicAdd (&global_count, total);
   170	            warps_buffer[warp_id] = old;
   171	          }
   172	          int old_global_voxels_count = warps_buffer[warp_id];
   173	
   174	          int offs = Warp::binaryExclScan (__ballot_sync (__activemask (), numVerts > 0));
   175	
   176	          if (old_global_voxels_count + offs < max_size && numVerts > 0)
   177	          {
   178	            voxels_indeces[old_global_voxels_count + offs] = VOLUME_Y * VOLUME_X * z + VOLUME_X * y + x;
   179	            vetexes_number[old_global_voxels_count + offs] = numVerts;
   180	          }
   181	
   182	          bool full = old_global_voxels_count + total >= max_size;
   183	
   184	          if (full)
   185	            break;
   186	
   187	        } /* for(int z = 0; z < VOLUME_Z - 1; z++) */
   188	
   189	
   190	        /////////////////////////
   191	        // prepare for future scans
   192	        if (ftid == 0)
   193	        {
   194	          unsigned int total_blocks = gridDim.x * gridDim.y * gridDim.z;
   195	          unsigned int value = atomicInc (&blocks_done, total_blocks);
   196	
   197	          //last block
   198	          if (value == total_blocks - 1)
   199	          {
   200	            output_count = min (max_size, global_count);
   201	            blocks_done = 0;
   202	            global_count = 0;
   203	          }
   204	        } 
   205	      } /* operator () */
   206	    };
