 70	    template<typename T> __device__ __forceinline__ T readClamped(const PtrStepSz<T>& image, int x, int y)
 71	    {
 72	      x = max(0, min(x, image.cols - 1));
 73	      y = max(0, min(y, image.rows - 1));
 74	      return image.ptr(y)[x];
