1878	__global__ void BlendFramesKernel(const float *u, const float *v,   // forward flow
1879	                                  const float *ur, const float *vr, // backward flow
1880	                                  const float *o0, const float *o1, // coverage masks
1881	                                  int w, int h, int s, 
1882	                                  float theta, float *out)
1883	{
1884	    const int ix = threadIdx.x + blockDim.x * blockIdx.x;
1885	    const int iy = threadIdx.y + blockDim.y * blockIdx.y;
1886	
1887	    const int pos = ix + s * iy;
1888	
1889	    if (ix >= w || iy >= h) return;
1890	
1891	    float _u = u[pos];
1892	    float _v = v[pos];
1893	
1894	    float _ur = ur[pos];
1895	    float _vr = vr[pos];
1896	
1897	    float x = (float)ix + 0.5f;
1898	    float y = (float)iy + 0.5f;
1899	    bool b0 = o0[pos] > 1e-4f;
1900	    bool b1 = o1[pos] > 1e-4f;
1901	
1902	    if (b0 && b1)
1903	    {
1904	        // pixel is visible on both frames
1905	        out[pos] = tex2D(tex_src0, x - _u * theta, y - _v * theta) * (1.0f - theta) + 
1906	            tex2D(tex_src1, x + _u * (1.0f - theta), y + _v * (1.0f - theta)) * theta;
1907	    }
1908	    else if (b0)
1909	    {
1910	        // visible on the first frame only
1911	        out[pos] = tex2D(tex_src0, x - _u * theta, y - _v * theta);
1912	    }
1913	    else
1914	    {
1915	        // visible on the second frame only
1916	        out[pos] = tex2D(tex_src1, x - _ur * (1.0f - theta), y - _vr * (1.0f - theta));
1917	    }
1918	}
