2346	    const int ix = blockIdx.x * blockDim.x + threadIdx.x;
2347	    const int iy = blockIdx.y * blockDim.y + threadIdx.y;
2348	
2349	    if (ix >= dstROI.width || iy >= dstROI.height)
2350	    {
