2364	    // y sampling range
2365	    float yBegin = fmax (y - scaleY, 0.0f);
2366	    float yEnd   = fmin (y + scaleY, rh - 1.0f);
2367	    // x range of source samples
2368	    float floorXBegin = std::floor (xBegin);
2369	    float ceilXEnd    = std::ceil (xEnd);
2370	    int iXBegin = srcROI.x + (int) floorXBegin;
2371	    int iXEnd   = srcROI.x + (int) ceilXEnd;
2372	    // y range of source samples
2373	    float floorYBegin = std::floor (yBegin);
2374	    float ceilYEnd    = std::ceil (yEnd);
2375	    int iYBegin = srcROI.y + (int) floorYBegin;
2376	    int iYEnd   = srcROI.y + (int) ceilYEnd;
2377	
2378	    // first row
2379	    int pos = iYBegin * srcStep + iXBegin;
2380	
2381	    float wsum = 1.0f - yBegin + floorYBegin;
2382	
2383	    float sum = processLine (pos, xBegin, xEnd, iXBegin, iXEnd, floorXBegin,
2384	        ceilXEnd) * (1.0f - yBegin + floorYBegin);
2385	    pos += srcStep;
2386	    for (int iy = iYBegin + 1; iy < iYEnd; ++iy)
2387	    {
2388	        sum += processLine (pos, xBegin, xEnd, iXBegin, iXEnd, floorXBegin,
2389	            ceilXEnd);
2390	        pos += srcStep;
2391	        wsum += 1.0f;
2392	    }
2393	
2394	    sum += processLine (pos, xBegin, xEnd, iXBegin, iXEnd, floorXBegin,
2395	        ceilXEnd) * (ceilYEnd - yEnd);
2396	    wsum += ceilYEnd - yEnd;
