2404	__forceinline__
2405	__device__ float bicubicCoeff(float x_)
2406	{
2407	    float x = std::abs(x_);
2408	    if (x <= 1.0f)
2409	    {
2410	        return x * x * (1.5f * x - 2.5f) + 1.0f;
2411	    }
2412	    else if (x < 2.0f)
2413	    {
2414	        return x * (x * (-0.5f * x + 2.5f) - 4.0f) + 2.0f;
2415	    }
2416	    else
2417	    {
2418	        return 0.0f;
2419	    }
2420	}
