2422	
2423	__global__ void resizeBicubic(NcvSize32u srcSize,
2424	                              NcvRect32u srcROI,
2425	                              NcvSize32u dstSize,
2426	                              Ncv32u dstStep,
2427	                              Ncv32f *dst,
2428	                              NcvRect32u dstROI,
2429	                              Ncv32f scaleX,
2430	                              Ncv32f scaleY)
2431	{
2432	    const int ix = blockIdx.x * blockDim.x + threadIdx.x;
2433	    const int iy = blockIdx.y * blockDim.y + threadIdx.y;
2434	
2435	    if (ix >= dstROI.width || iy >= dstROI.height)
2436	    {
2437	        return;
2438	    }
2439	
2440	    const float dx = 1.0f / srcROI.width;
2441	    const float dy = 1.0f / srcROI.height;
2442	
2443	    float rx = (float) srcROI.x;
2444	    float ry = (float) srcROI.y;
2445	
2446	    float rw = (float) srcROI.width;
2447	    float rh = (float) srcROI.height;
2448	
2449	    float x = scaleX * (float) ix;
2450	    float y = scaleY * (float) iy;
2451	
2452	    // sampling range
2453	    // border mode is clamp
2454	    float xmin = fmax (std::ceil (x - 2.0f), 0.0f);
2455	    float xmax = fmin (std::floor (x + 2.0f), rw - 1.0f);
2456	
2457	    float ymin = fmax (std::ceil (y - 2.0f), 0.0f);
2458	    float ymax = fmin (std::floor (y + 2.0f), rh - 1.0f);
2459	
2460	    // shift data window to match ROI
2461	    rx += 0.5f;
2462	    ry += 0.5f;
2463	
2464	    x += rx;
2465	    y += ry;
2466	
2467	    xmin += rx;
2468	    xmax += rx;
2469	    ymin += ry;
2470	    ymax += ry;
2471	
2472	    float sum  = 0.0f;
2473	    float wsum = 0.0f;
2474	
2475	    for (float cy = ymin; cy <= ymax; cy += 1.0f)
2476	    {
2477	        for (float cx = xmin; cx <= xmax; cx += 1.0f)
2478	        {
2479	            float xDist = x - cx;
2480	            float yDist = y - cy;
2481	            float wx = bicubicCoeff (xDist);
2482	            float wy = bicubicCoeff (yDist);
2483	            wx *= wy;
2484	            sum += wx * tex2D (texSrc2D, cx * dx, cy * dy);
2485	            wsum += wx;
2486	        }
2487	    }
2488	    dst[(ix + dstROI.x)+ (iy + dstROI.y) * dstStep] = (!wsum)? 0 : sum / wsum;
2489	}
